sys_script.script:
(function executeRule(current, previous /*null when async*/) {


	var priority = current.getValue('priority');

if (!priority) {
gs.addErrorMessage('MIM SLA: Priority is empty.');
return;
}

priority = priority.toLowerCase();

var responseMinutes;
var resolutionHours;

if (priority == '1') {
responseMinutes = 5;
resolutionHours = 1;
} else if (priority == '2') {
responseMinutes = 15;
resolutionHours = 4;
} else if (priority == '3') {
responseMinutes = 30;
resolutionHours = 8;
} else if (priority == '4') {
responseMinutes = 60;
resolutionHours = 24;
} else {
gs.addErrorMessage('MIM SLA: Invalid priority: ' + priority);
return;
}

var now = new GlideDateTime();

var responseDue = new GlideDateTime();
responseDue.addSeconds(responseMinutes * 60);

var resolutionDue = new GlideDateTime();
resolutionDue.addSeconds(resolutionHours * 3600);

current.setValue('response_due', responseDue.getValue());
current.setValue('resolution_due', resolutionDue.getValue());
current.setValue('sla_status', 'in progress');


if (current.isNewRecord()) {
current.setValue('response_breached', false);
current.setValue('resolution_breached', false);
}

gs.info('MIM SLA DEBUG: Priority=' + priority +
', Response Due=' + current.getValue('response_due') +
', Resolution Due=' + current.getValue('resolution_due'));

})(current, previous);
